parameters.command:
python3 << 'EOF'
import json

FLOW_PATH = "/work/output/artifacts/skill-flow-ixp-routing/invoice-extraction/InvoiceExtractionSolution/InvoiceExtraction/InvoiceExtraction.flow"

with open(FLOW_PATH) as f:
    flow = json.load(f)

# Load definitions from registry
with open('/tmp/ixp_def_pretty.json') as f:
    ixp_def = json.load(f)
with open('/tmp/end_def_pretty.json') as f:
    end_def = json.load(f)
with open('/tmp/script_def_pretty.json') as f:
    script_def = json.load(f)

IXP_NODE_TYPE = "uipath.ixp.idp-benchmark-invoices-c735405a-ixp.f6df6382-0af4-80b4-9690-e540cf2af19a-c4359cde-55f0-4f0e-9322-c6cdce74ab4c"
IXP_FOLDER_KEY = "c4359cde-55f0-4f0e-9322-c6cdce74ab4c"
IXP_MODEL_ID = "f6df6382-0af4-80b4-9690-e540cf2af19a"
IXP_MODEL_NAME = "idp-benchmark---invoices-c735405a-ixp"

# IxP output definition (from registry)
ixp_output_def = ixp_def["outputDefinition"]

# Script node for parsing extracted fields
PARSE_SCRIPT = """const fields = $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument.Fields || [];
function fv(name) {
  const f = fields.find(function(x) { return x.FieldName === name; });
  return f && f.Values && f.Values.length > 0 ? f.Values[0] : null;
}
const tables = $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument.Tables || [];
const lineItems = tables.length > 0 ? tables[0].Values : [];
return {
  vendorName: fv('vendor_name') || fv('VendorName') || fv('Vendor'),
  invoiceNumber: fv('invoice_id') || fv('InvoiceNumber') || fv('InvoiceId'),
  invoiceDate: fv('invoice_date') || fv('InvoiceDate'),
  totalAmount: fv('invoice_total') || fv('TotalAmount') || fv('Total'),
  lineItems: lineItems
};"""

# New nodes to add
new_nodes = [
    {
        "id": "extractInvoiceFields1",
        "type": IXP_NODE_TYPE,
        "typeVersion": "1.0.0",
        "display": {"label": "Extract Invoice Fields"},
        "inputs": {
            "model": {
                "id": IXP_MODEL_ID,
                "modelName": IXP_MODEL_NAME,
                "modelDisplayName": IXP_MODEL_NAME,
                "folderKey": IXP_FOLDER_KEY,
                "folderName": "Shared",
                "folderPath": IXP_FOLDER_KEY,
                "description": ""
            },
            "modelName": IXP_MODEL_NAME,
            "projectName": IXP_MODEL_NAME,
            "folderKey": IXP_FOLDER_KEY,
            "folderName": "Shared",
            "versionTag": "",
            "pageRange": "",
            "fileRef": "=js:$vars.downloadInvoicePdf1.output"
        },
        "outputs": {
            "output": ixp_output_def["output"],
            "error": ixp_output_def["error"]
        }
    },
    {
        "id": "parseInvoiceFields1",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": {"label": "Parse Invoice Fields"},
        "inputs": {
            "language": "javascript",
            "script": PARSE_SCRIPT
        },
        "outputs": {
            "output": {
                "type": "object",
                "description": "The return value of the script",
                "source": "=result.response",
                "var": "output"
            }
        }
    },
    {
        "id": "end1",
        "type": "core.control.end",
        "typeVersion": "1.0",
        "display": {"label": "End"}
    }
]

flow["nodes"].extend(new_nodes)

# Add definitions (avoid duplicates)
existing_types = {d.get("nodeType") for d in flow["definitions"]}

if IXP_NODE_TYPE not in existing_types:
    flow["definitions"].append(ixp_def)
if "core.action.script" not in existing_types:
    flow["definitions"].append(script_def)
if "core.control.end" not in existing_types:
    flow["definitions"].append(end_def)

# Wire edges:
# newInvoiceInSharepoint1.output → downloadInvoicePdf1.input
# downloadInvoicePdf1.output → extractInvoiceFields1.input
# extractInvoiceFields1.success → parseInvoiceFields1.input
# parseInvoiceFields1.success → postInvoiceToAccounting1.input
# postInvoiceToAccounting1.output → end1.input
new_edges = [
    {
        "id": "e-trigger-download",
        "sourceNodeId": "newInvoiceInSharepoint1",
        "sourceHandle": "output",
        "targetNodeId": "downloadInvoicePdf1",
        "targetPort": "input"
    },
    {
        "id": "e-download-extract",
        "sourceNodeId": "downloadInvoicePdf1",
        "sourceHandle": "output",
        "targetNodeId": "extractInvoiceFields1",
        "targetPort": "input"
    },
    {
        "id": "e-extract-parse",
        "sourceNodeId": "extractInvoiceFields1",
        "sourceHandle": "success",
        "targetNodeId": "parseInvoiceFields1",
        "targetPort": "input"
    },
    {
        "id": "e-parse-post",
        "sourceNodeId": "parseInvoiceFields1",
        "sourceHandle": "success",
        "targetNodeId": "postInvoiceToAccounting1",
        "targetPort": "input"
    },
    {
        "id": "e-post-end",
        "sourceNodeId": "postInvoiceToAccounting1",
        "sourceHandle": "output",
        "targetNodeId": "end1",
        "targetPort": "input"
    }
]
flow["edges"].extend(new_edges)

# Add variables.nodes for new data-producing nodes
ixp_vars = [
    {
        "id": "extractInvoiceFields1.output",
        "type": "object",
        "description": "Extraction result from IxP invoice model",
        "binding": {"nodeId": "extractInvoiceFields1", "outputId": "output"}
    },
    {
        "id": "extractInvoiceFields1.error",
        "type": "object",
        "description": "Error from IxP invoice extraction",
        "binding": {"nodeId": "extractInvoiceFields1", "outputId": "error"}
    },
    {
        "id": "parseInvoiceFields1.output",
        "type": "object",
        "description": "Parsed invoice fields",
        "binding": {"nodeId": "parseInvoiceFields1", "outputId": "output"}
    }
]
flow["variables"]["nodes"].extend(ixp_vars)

# Add layout entries for new nodes
flow["layout"]["nodes"]["extractInvoiceFields1"] = {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}
flow["layout"]["nodes"]["parseInvoiceFields1"] = {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}
flow["layout"]["nodes"]["end1"] = {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}

with open(FLOW_PATH, "w") as f:
    json.dump(flow, f, indent=2)

print("Done - flow written successfully")
EOF

